const { sortByTransactionId, sortByNoticeId } = require("../utils/sort");

const STATUS_ORDER = { pending: 0, approved: 1, rejected: 2, reversed: 3 };

function maxStatus(a, b) {
  const sa = String(a || "").toLowerCase();
  const sb = String(b || "").toLowerCase();
  if (!(sa in STATUS_ORDER)) return sb;
  if (!(sb in STATUS_ORDER)) return sa;
  return STATUS_ORDER[sa] >= STATUS_ORDER[sb] ? sa : sb;
}

function reconcileTransactions(parsed) {
  // Base load from ledger
  const byId = new Map();
  for (const row of parsed.ledger) {
    byId.set(row.transaction_id, {
      transaction_id: row.transaction_id,
      owner: row.owner,
      status: String(row.status).toLowerCase(),
      date: row.date,
      amount: Number(row.amount),
      // derived/tracking
      _hadStatusCorrection: false,
      _preCorrectionDate: row.date,
    });
  }

  // Meeting amendments: only signed amendments affect owner
  for (const meeting of parsed.meetings) {
    if (!meeting || !meeting.transaction_id) continue;
    if (!meeting.signed) continue;
    const target = byId.get(meeting.transaction_id);
    if (target && meeting.owner) {
      target.owner = meeting.owner;
    }
  }

  // Emails: only qualifying compliance@ senders can change status.
  // Apply by status precedence (choose max).
  const qualifyingEmailsByTxn = new Map();
  for (const email of parsed.emails) {
    if (!email || !email.transaction_id) continue;
    if (!email.qualifying) continue;
    const target = byId.get(email.transaction_id);
    if (target && email.status) {
      target.status = maxStatus(target.status, email.status);
    }
    if (!qualifyingEmailsByTxn.has(email.transaction_id)) {
      qualifyingEmailsByTxn.set(email.transaction_id, []);
    }
    qualifyingEmailsByTxn.get(email.transaction_id).push(email);
  }

  // Snapshot "ledger date immediately before correction notices are applied"
  // for compliance_hold comparison (Brief 09): after ledger+meetings+emails.
  for (const t of byId.values()) {
    t._preCorrectionDate = t.date;
  }

  // Correction notices: choose winning notice per (transaction_id, field)
  // by lexicographically greatest effective date (YYYY-MM-DD).
  const winnerByKey = new Map();
  for (const notice of parsed.corrections) {
    if (!notice || !notice.transaction_id || !notice.field || !notice.effective) continue;
    if (!byId.has(notice.transaction_id)) continue;
    const field = notice.field.trim();
    const key = `${notice.transaction_id}::${field}`;
    const prev = winnerByKey.get(key);
    if (!prev) {
      winnerByKey.set(key, notice);
      continue;
    }
    if (notice.effective > prev.effective) {
      winnerByKey.set(key, notice);
    } else if (notice.effective === prev.effective) {
      // deterministic tie-break
      if (String(notice.notice_id) > String(prev.notice_id)) {
        winnerByKey.set(key, notice);
      }
    }
  }

  const winners = Array.from(winnerByKey.values());
  // Apply in ascending effective then notice_id to ensure previous_value is correct.
  winners.sort((a, b) => {
    if (a.effective === b.effective) {
      if (a.notice_id === b.notice_id) return 0;
      return a.notice_id < b.notice_id ? -1 : 1;
    }
    return a.effective < b.effective ? -1 : 1;
  });

  const report = [];
  for (const notice of winners) {
    const target = byId.get(notice.transaction_id);
    if (!target) continue;

    let previousValue;
    if (notice.field === "owner") previousValue = String(target.owner ?? "");
    else if (notice.field === "status") previousValue = String(target.status ?? "");
    else if (notice.field === "date") previousValue = String(target.date ?? "");
    else previousValue = "";

    // Apply correction
    if (notice.field === "owner") {
      target.owner = notice.value;
    } else if (notice.field === "status") {
      if (String(target.status).toLowerCase() !== String(notice.value).toLowerCase()) {
        target._hadStatusCorrection = true;
      }
      target.status = String(notice.value).toLowerCase();
      // Brief 06: effective_date becomes correction effective when status/date corrected
      target.date = notice.effective;
    } else if (notice.field === "date") {
      target.date = notice.value;
      // Brief 06: effective_date becomes correction effective when status/date corrected
      target.date = notice.effective;
    }

    report.push({
      notice_id: notice.notice_id,
      transaction_id: notice.transaction_id,
      field: notice.field,
      previous_value: previousValue,
      new_value: String(notice.value),
      effective: notice.effective,
    });
  }

  // Sort report by notice_id ascending for output.
  sortByNoticeId(report);

  const items = sortByTransactionId(
    [...byId.values()].map((row) => ({
      transaction_id: row.transaction_id,
      owner: row.owner,
      status: String(row.status).toLowerCase(),
      effective_date: row.date,
      amount_usd: Number(row.amount),
      exception_reason: null,
      // internal
      _preCorrectionDate: row._preCorrectionDate,
      _qualifyingEmails: qualifyingEmailsByTxn.get(row.transaction_id) || [],
      _hadStatusCorrection: row._hadStatusCorrection,
    })),
  );

  return { items, report };
}

module.exports = { reconcileTransactions, STATUS_ORDER };
EOF

