function buildExceptionReason(row, policyMap) {
  const reasons = [];

  const amount = Number(row.amount_usd);
  const status = String(row.status).toLowerCase();

  if (Number.isFinite(amount) && amount > 10000) {
    reasons.push("over_limit");
  }

  // compliance_hold: final status rejected AND qualifying compliance email exists
  // with a sent: line AND sent date is after the pre-correction date snapshot.
  if (status === "rejected") {
    const pre = row._preCorrectionDate;
    const emails = Array.isArray(row._qualifyingEmails) ? row._qualifyingEmails : [];
    const hasLate = emails.some((e) => e && e.sent && pre && String(e.sent) > String(pre));
    if (hasLate) {
      reasons.push("compliance_hold");
    }
  }

  // policy_waiver: final status approved, amount > 10000,
  // and Policy Exception exists with approved_by: compliance
  if (status === "approved" && Number.isFinite(amount) && amount > 10000) {
    const approvedBy = policyMap && policyMap.get ? policyMap.get(row.transaction_id) : null;
    if (approvedBy && String(approvedBy).trim().toLowerCase() === "compliance") {
      reasons.push("policy_waiver");
    }
  }

  // retroactive_review: final status reversed, amount > 5000,
  // and a winning correction notice changed status
  if (status === "reversed" && Number.isFinite(amount) && amount > 5000 && row._hadStatusCorrection) {
    reasons.push("retroactive_review");
  }

  reasons.sort();
  return reasons.length ? reasons.join(";") : null;
}

function buildExceptions(items, policyMap) {
  const normalized = items.map((row) => ({
    ...row,
    exception_reason: buildExceptionReason(row, policyMap),
  }));
  const exceptions = normalized.filter((row) => row.exception_reason !== null);
  return { items: normalized, exceptions };
}

module.exports = { buildExceptions };
EOF

