const fs = require("node:fs");

function csvEscape(value) {
  if (value === null || value === undefined) return "";
  const s = String(value);
  if (/[",\n]/.test(s)) {
    return '"' + s.replace(/"/g, '""') + '"';
  }
  return s;
}

function writeTransactionsCsv(filePath, items) {
  const header =
    "transaction_id,owner,status,effective_date,amount_usd,exception_reason";
  const lines = items.map((row) => {
    const amt = Number(row.amount_usd);
    const amtStr = Number.isFinite(amt) ? amt.toFixed(2) : "";
    return [
      csvEscape(row.transaction_id),
      csvEscape(row.owner),
      csvEscape(row.status),
      csvEscape(row.effective_date),
      csvEscape(amtStr),
      csvEscape(row.exception_reason === null ? "" : row.exception_reason),
    ].join(",");
  });
  fs.writeFileSync(filePath, [header, ...lines].join("\n") + "\n");
}

module.exports = { writeTransactionsCsv };
